"""Mission 0 - Depot - thin host generated by tools/ae_new_mission.py (RPE6 P10).

Plays: briefing dialogue -> depot sweep -> exit -> outro cutscene
(inspect shot + 3D shot).  All content is data (see content files);
this module is the game-side glue the tutorial describes.  No engine
edits: level via game.levels, dialogue via engine.dialogue, cutscene
shots via game.timelines + registered renderers, set via
game.render3d_bridge, HUD plate via engine.ui.std.
"""
from __future__ import annotations

import json
import math
import os

import pygame

from core.config import HEIGHT, TILE_SIZE, WIDTH, screen
from core.cutscene_registry import register_scene_renderer
from core.state import STATE
from cutscenes import draw_dialogue_box
from engine.dialogue import DialogueRunner
from entities.enemy_ai import Enemy
from entities.player import Player
from game import dialogues as _dialogues, levels as _levels, timelines as _timelines

MISSION_ID = "mission0"
_PKG = "m0"
_LEVEL_ID = "mission0.depot"
_DIALOGUE_ID = "mission0.briefing"
_TIMELINE_ID = "mission0.outro"
_SET_ID = "mission0.depot"

_DATA = json.loads(open(os.path.join(os.path.dirname(os.path.abspath(__file__)),
                                     "enemy_types.json"), encoding="utf-8").read())
_TYPES = _DATA["enemy_types"]

_S = {"phase": "idle", "runner": None, "line": None, "prev_advance": False,
      "outro_requested": False, "exit_rects": [], "result": None}

# ── dialogue host (engine.dialogue.DialogueHost protocol) ──────────────


class _Host:
    def flag(self, name):
        return bool(_S.get("flags", {}).get(name))

    def var(self, name):
        return _S.get("vars", {}).get(name)

    def set_var(self, name, value):
        _S.setdefault("vars", {})[name] = value

    def emit(self, name, payload=None):
        _S["last_event"] = (name, payload)

    def resolve(self, node):
        return node.get("text", "")

    def speaker_meta(self, speaker):
        return {}


# ── cutscene renderers (registered by scene id) ────────────────────────

_R3D = {"r": None, "buf": None}


def _draw_inspect(surface, t):
    surface.fill((14, 16, 20))
    cx, cy = WIDTH // 2, 300
    pygame.draw.rect(surface, (70, 60, 44), (cx - 130, cy - 90, 260, 180))
    pygame.draw.rect(surface, (150, 132, 92), (cx - 130, cy - 90, 260, 180), 3)
    pygame.draw.rect(surface, (170, 40, 40), (cx - 90, cy - 30, 180, 34))
    from core.config import font_terminal, font_terminal_small
    tag = font_terminal.render("SUPPLY CRATE", True, (226, 214, 180))
    surface.blit(tag, (cx - tag.get_width() // 2, cy - 24))
    sub = font_terminal_small.render("MANIFEST 114 - MEDICAL - GUARD STAMP", True, (180, 172, 150))
    surface.blit(sub, (cx - sub.get_width() // 2, cy + 116))


def _rend3d():
    """Shared 480x270-class render buffer, resized with the quality
    tier's render scale (P11 low-end pass); recreated on tier change."""
    from engine3d import Renderer
    from game import render3d_bridge as _bridge
    w, h = _bridge.render_size_3d()
    if _R3D["r"] is None or _R3D.get("size") != (w, h):
        _R3D["r"] = Renderer(w, h)
        _R3D["buf"] = pygame.Surface((w, h))
        _R3D["size"] = (w, h)
    return _R3D["r"], _R3D["buf"]


def _draw_depot3d(surface, t):
    from engine3d import Renderer
    from engine3d.core import box, quad_xz
    from game import render3d_bridge as _bridge
    r, buf = _rend3d()
    k = min(1.0, t / 3200.0)
    # Camera stays inside the depot (the scaffold path drifted outside
    # the back wall and the outro played against a blank wall - B-039).
    eye = (3.6 - 0.8 * k, 2.5 - 0.4 * k, -2.5 + 0.5 * k)
    r.set_camera(eye, (-1.0, 0.6, 0.8), 58)
    # Phase 11 step 1: the set's lighting preset, cross-fading a touch
    # warmer over the shot (preset_blend through the bridge).
    from engine3d.core import Light
    _L = _bridge.set_lighting(_SET_ID, blend=("night_interior", "office_day", 0.25 * k))
    _key = _L["key"]
    r.light = Light(direction=tuple(_key["direction"]), ambient=_key["ambient"],
                    diffuse=_key["diffuse"], tint=tuple(_key["tint"]))
    r.fog, r.fog_start, r.fog_end = (tuple(_L["fog"]["color"]), _L["fog"]["start"],
                                     _L["fog"]["end"])
    buf.fill(tuple(_L["fog"]["color"]))
    r.begin()
    from core.cutscene_registry import current_shot as _shot_now
    _params = {"t": t / 1000.0}
    _params.update((_shot_now() or {}).get("set_params") or {})
    _prims = _bridge.set_prims(_SET_ID, params=_params)
    _bridge.emit_lights(r, _prims)
    _bridge.emit_shadows(r, _prims)
    _bridge.push_textures(r, _prims)
    _pairs = [(prim, _bridge.build_mesh(prim))  # seg/AO honoured (P11)
              for prim in _prims if prim["kind"] in ("box", "quad_xz")]
    _bridge.bake_cast_shadows(_pairs, _prims)  # ADR-023 baked cast shadows
    for prim, m in _pairs:
        r.add_dynamic(m.verts, _bridge.dynamic_faces(m))
    from cutscenes import weather3d  # depot steam vent (P11 step 6, set data)
    weather3d.attach(r, _prims, t)
    # Phase 11 step 5: DOF from the shot's post block (data), quality-gated
    from core.cutscene_registry import current_shot
    _post = (current_shot() or {}).get("post") or {}
    _dof_s = float(_post.get("dof_strength", 0) or 0)
    if _dof_s > 0 and _bridge.quality_3d() >= 2:
        _focus = float(_post.get("dof_focus", 6.0))

        def _soften(s):
            _sm = pygame.transform.smoothscale(s, (160, 90))
            s.blit(pygame.transform.smoothscale(_sm, s.get_size()), (0, 0))

        r.flush_split(buf, _focus, _soften)
    else:
        r.flush(buf)
    surface.fill((0, 0, 0))
    scaled = pygame.transform.smoothscale(buf, (WIDTH, 405))
    surface.blit(scaled, (0, 147))


def _draw_yard3d(surface, t):
    """Depot yard in the rain (Phase 11 step 6: weather from set data)."""
    from cutscenes import m5fx3d as _fx
    from cutscenes import weather3d
    from engine3d import Renderer
    from game import render3d_bridge as _bridge
    r, buf = _rend3d()
    k = min(1.0, t / 3600.0)
    r.set_camera((5.2 - 1.2 * k, 2.4 - 0.3 * k, -4.8 + 0.8 * k), (-0.4, 1.1, 2.4), 57)
    from engine3d.core import Light
    _L = _bridge.set_lighting("mission0.yard")
    _key = _L["key"]
    r.light = Light(direction=tuple(_key["direction"]), ambient=_key["ambient"],
                    diffuse=_key["diffuse"], tint=tuple(_key["tint"]))
    r.fog, r.fog_start, r.fog_end = (tuple(_L["fog"]["color"]), _L["fog"]["start"],
                                     _L["fog"]["end"])
    buf.fill(tuple((_L["sky"] or [[16, 20, 28]])[0]))

    def _add(rr, m):
        rr.add_dynamic(m.verts, _bridge.dynamic_faces(m))

    def _spr(rr, pos, fn):
        rr.add_sprite(pos, fn)

    r.begin()
    from core.cutscene_registry import current_shot as _shot_now_y
    _params_y = {"t": t / 1000.0}
    _params_y.update((_shot_now_y() or {}).get("set_params") or {})
    _prims = _bridge.set_prims("mission0.yard", params=_params_y)
    _bridge.apply_set(r, _prims, add=_add, dec=_add, spr=_spr,
                      decal_add=lambda *a, **kw: False, fx=_fx, t=t)
    weather3d.attach(r, _prims, t, fx=_fx)
    r.flush(buf)
    surface.fill((0, 0, 0))
    surface.blit(pygame.transform.smoothscale(buf, (WIDTH, 405)), (0, 147))


register_scene_renderer(_PKG + "_inspect", _draw_inspect)
register_scene_renderer(_PKG + "_depot3d", _draw_depot3d)
register_scene_renderer(_PKG + "_yard3d", _draw_yard3d)


# ── lifecycle ───────────────────────────────────────────────────────────


def outro_shots():
    return _timelines.shots(_TIMELINE_ID, [])


def take_outro_request() -> bool:
    if _S["outro_requested"]:
        _S["outro_requested"] = False
        return True
    return False


def complete() -> bool:
    return _S["phase"] == "done"


def start_mission0(preserve_timer=False):
    level = _levels.level(_LEVEL_ID)
    grid = level.grid("floor")
    tile = level.tile_size
    _S.update(phase="briefing", outro_requested=False, result=None)
    _S["flags"], _S["vars"] = {}, {}
    walls, exits = [], []
    for ty, row in enumerate(grid):
        for tx, ch in enumerate(row):
            if ch == "#":
                walls.append(pygame.Rect(tx * tile, ty * tile, tile, tile))
            elif ch == "=":
                exits.append(pygame.Rect(tx * tile, ty * tile, tile, tile))
    _S["exit_rects"] = exits
    STATE.walls = walls
    STATE.bullets = []
    STATE.particles = []
    STATE.enemies = []
    STATE.doors = []
    player = None
    for obj in level.objects:
        tile_xy = obj.get("tile", [0, 0])
        x, y = tile_xy[0] * tile + tile // 2, tile_xy[1] * tile + tile // 2
        who = (obj.get("props") or {}).get("who")
        if obj.get("kind") == "spawn" and who == "player":
            player = Player(x - 16, y - 16)
        elif obj.get("kind") == "spawn" and who == "enemy":
            etype = (obj.get("props") or {}).get("type", "sentinel")
            spec = _TYPES[etype]
            e = Enemy(x - 16, y - 16)
            e.hp = spec["hp"]
            e.speed = spec["speed"]
            e.sight_mul = spec["sight_mul"]
            STATE.enemies.append(e)
    STATE.player = player
    STATE.active_mission = "MISSION0"
    STATE.camera_x, STATE.camera_y = 0, 0
    runner = DialogueRunner(_dialogues.dialogue(_DIALOGUE_ID), _Host())
    _S["runner"] = runner
    _S["line"] = runner.begin()
    return player


# ── update ──────────────────────────────────────────────────────────────


def _advance_down(keys) -> bool:
    return bool(keys[pygame.K_SPACE] or keys[pygame.K_RETURN])


def _move_player(keys):
    p = STATE.player
    if p is None:
        return
    dx = (keys[pygame.K_d] or keys[pygame.K_RIGHT]) - (keys[pygame.K_a] or keys[pygame.K_LEFT])
    dy = (keys[pygame.K_s] or keys[pygame.K_DOWN]) - (keys[pygame.K_w] or keys[pygame.K_UP])
    if dx and dy:
        dx, dy = dx * 0.7071, dy * 0.7071
    speed = 3.0
    r = p.rect
    r.x += int(round(dx * speed))
    for w in STATE.walls:
        if r.colliderect(w):
            r.x = w.left - r.w if dx > 0 else w.right
    r.y += int(round(dy * speed))
    for w in STATE.walls:
        if r.colliderect(w):
            r.y = w.top - r.h if dy > 0 else w.bottom
    if dx or dy:
        p.angle = math.atan2(dy, dx)


def _step_bullets():
    p = STATE.player
    keep = []
    for b in STATE.bullets:
        b["x"] += b["dx"]
        b["y"] += b["dy"]
        b["life"] -= 1
        if b["life"] <= 0:
            continue
        if any(w.collidepoint(b["x"], b["y"]) for w in STATE.walls):
            continue
        if p is not None and b.get("owner") == "enemy":
            if (b["x"] - p.rect.centerx) ** 2 + (b["y"] - p.rect.centery) ** 2 < 18 ** 2:
                p.hp -= b.get("damage", 8)
                continue
        keep.append(b)
    STATE.bullets = keep


def game_update(keys):
    if _S["phase"] == "briefing":
        down = _advance_down(keys)
        if down and not _S["prev_advance"]:
            _S["line"] = _S["runner"].advance()
            if _S["runner"].ended or _S["line"] is None:
                _S["phase"] = "play"
        _S["prev_advance"] = down
        return (0, 0)
    if _S["phase"] != "play" or STATE.player is None:
        return (0, 0)
    _move_player(keys)
    px, py = STATE.player.rect.centerx, STATE.player.rect.centery
    for e in list(STATE.enemies):
        e.update(px, py, STATE.walls, STATE.bullets, STATE.particles)
    STATE.enemies = [e for e in STATE.enemies if e.hp > 0]
    _step_bullets()
    for pt in list(STATE.particles):
        pt.update()
    STATE.particles = [pt for pt in STATE.particles if pt.life > 0]
    if STATE.player.hp <= 0:
        start_mission0()          # fail -> restart (tutorial-simple)
        return (0, 0)
    for ex in _S["exit_rects"]:
        if STATE.player.rect.colliderect(ex):
            _S["phase"] = "done"
            _S["outro_requested"] = True
            break
    return (0, 0)


# ── draw (one CustomDraw via the render host, like M1-M4) ──────────────


def game_draw(fcx=0, fcy=0):
    surface = screen
    tile = TILE_SIZE
    surface.fill((18, 20, 24))
    level = _levels.level(_LEVEL_ID)
    for ty, row in enumerate(level.grid("floor")):
        for tx, ch in enumerate(row):
            x, y = tx * tile, ty * tile
            if ch == "#":
                pygame.draw.rect(surface, (58, 56, 52), (x, y, tile, tile))
                pygame.draw.rect(surface, (38, 37, 35), (x, y, tile, tile), 2)
            elif ch == "=":
                pygame.draw.rect(surface, (36, 72, 48), (x, y, tile, tile))
            else:
                pygame.draw.rect(surface, (30, 32, 34), (x, y, tile, tile))
    for e in STATE.enemies:
        pygame.draw.rect(surface, (150, 60, 50), e.rect)
    for b in STATE.bullets:
        pygame.draw.rect(surface, (240, 220, 150), (b["x"] - 2, b["y"] - 2, 4, 4))
    for pt in STATE.particles:
        pt.draw(surface, 0, 0)
    p = STATE.player
    if p is not None:
        pygame.draw.rect(surface, (80, 140, 220), p.rect)
    # HUD plate (engine.ui.std widgets + theme)
    from engine.ui import health_bar as _health_bar, objective_banner as _banner
    from ui.hud import THEME
    from entities.art_cache import get_panel_bg
    _banner.draw(surface, _DATA["objective"], THEME, x=20, y=16)
    if p is not None:
        _health_bar.draw(surface, THEME, p.hp, p.max_hp,
                         panel_bg=get_panel_bg, x=20, y=HEIGHT - 34)
    if _S["phase"] == "briefing" and _S["line"] is not None:
        line = _S["line"]
        _txt = getattr(line, "text", "")
        draw_dialogue_box(surface, getattr(line, "speaker", "") or "",
                          _txt, len(_txt), len(_txt))
    return None
